WITH base AS (SELECT id, product_name, category, brand, price, stock_qty, launch_date, tags, supplier_id, stock_qty - price AS stock_qty_minus_price, COALESCE(brand, 'DIRECT') AS brand_filled FROM products WHERE launch_date > TO_DATE('2023-04-03')), valid AS (SELECT *, LOWER(product_name) AS product_name_lower FROM base WHERE launch_date >= DATE '2023-03-17'), with_latest AS (SELECT s.*, latest.quantity FROM valid s LEFT JOIN LATERAL (SELECT c.quantity FROM inventory c WHERE c.product_id = s.id ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) latest ON TRUE), filtered AS (SELECT *, UPPER(category) AS category_upper, DATE_FORMAT(launch_date, 'MMM yyyy') AS launch_date_label FROM with_latest WHERE launch_date > TO_DATE('2023-07-05') AND supplier_id IS NOT NULL) SELECT d.city, s.brand, COUNT(*) AS num_rows, ROUND(SUM(s.price), 2) AS total_price, GROUPING_ID() AS level_id FROM filtered s INNER JOIN suppliers d ON s.supplier_id = d.id GROUP BY GROUPING SETS ((d.city, s.brand), (d.city), ())
